from build_reference import *

def run():
    dest=OUT/'joint_model/SC_connection';a=json.loads((dest/'assembly.json').read_text(encoding='utf8'));r=json.loads((dest/'bone_motion_audit.json').read_text(encoding='utf8'));capture=json.loads((dest/'capture_probes.json').read_text(encoding='utf8'));cad=json.loads((dest/'cad_roundtrip.json').read_text(encoding='utf8'));checks=json.loads((dest/'geometry_checks.json').read_text(encoding='utf8'))
    r['scope']='five moving bones vs32 bony envelopes and10 fixed SC cap/fastener solids; all adjacent moving pairs checked';r['included_SC_parts']=list(a['components']);r['derived_geometry_hashes']={n:hashlib.sha256((dest/(n+'.obj')).read_bytes()).hexdigest() for n in a['components']};r['GH_probe_frame']='flexion and abduction axes perpendicular to fitted humeral long axis, towards source anterior(-Y) / right(-X); rotation-vector controls, not Euler angles';r['not_included']=['AC/GH/elbow retention hardware','muscle motion/steel channels','printed tolerance, strength, force'];(dest/'bone_motion_audit.json').write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf8')
    text=['# 新关节候选与S1胸锁连接审查','','状态：几何候选，尚未定版。运动学采用SC3/AC3/GH3/肘1；没有继承旧链或旧动作底线。','SC已有实体候选，AC/GH/肘目前仍是理想约束，不能把整臂称为已经完成机械装配。','','## 为什么修改SC局部连接','',f"原始锁骨与胸骨柄在零位重叠{a['source_overlap_mm3']:.3f}mm³，原始骨形不能直接作为无干涉刚体装配。",'改为锁骨端球头＋颈部、胸骨柄局部座体、左右可拆保持盖、M3紧固件及垫片。','未删除连接来绕开碰撞；12件均为单一连通实体，零位逐件检查无报告阈值以上穿透。','各骨形切除/增加体积见assembly.json，简化表面容差0.01mm及零体积壳清理见mesh_cleanup.json。','骨骼上原候选肌肉区域的距离变化见geometry_checks.json；五个锁骨相关区域样点均未偏离新表面超过1mm。','','## 当前规定探测路径','','目标角度是用于找限制的探测范围，不是偷偷替换的新验收标准。','前屈/外展绕与拟合肱骨长轴正交的工程轴测量；轴向旋转绕肱骨长轴。','SC/AC行显示局部旋转向量参数，不冒充已标定的临床肩胛角。','联合抬升显示实际肱骨方向变化，不把SC、AC、GH角度直接相加。','','|路径|探测量|连续前缀参数|实际肱骨方向变化|首个限制|','|---|---:|---:|---:|---|']
    for row in r['actions']:
        q=np.array(row['requested_controls_deg']);amount=max(np.linalg.norm(q[:3]),np.linalg.norm(q[3:6]),np.linalg.norm(q[6:9]),abs(q[9]));limit='；'.join('/'.join(h['pair']) for h in row['first_limit']) or '所测路径未见穿透，未证明最大值';text.append(f"|{row['probe']}|{amount:.2f}°|{amount*row['continuous_prefix_fraction']:.2f}°|{row['actual_humerus_elevation_deg']:.2f}°|{limit}|")
    text+=['','骨骼＋SC零件按≤1°去回程采样，边界细化至0.1°；体积报告阈值0.001mm³，间隙查询上限3mm。','七个肋软骨只作参考，未作刚性通过项；肌肉变形未验收。','SC前后运动的孤立路径较小，是胸廓和锁骨/肩胛的耦合问题，不代表耦合运动的最大值。','后续应优化SC与AC配合路径，不能整对排除锁骨、肩胛、肋骨的碰撞来制造通过。','','## 保持与装配','','先将球头放入后座，再把两个保持盖从颈部两侧放入，以M3紧固件锁到座体。','不能强行把球头压过较小的保持口。螺钉/螺母是标准M3包络，不是可直接打印的螺纹加工图。','装配使用金属标准件；两个M3×16、两个螺母和四只垫片已建模。','螺纹、预紧、载荷与实际打印配合尚未验证。',f"六方向球头直线移出探测：{capture['all_six_straight_directions_blocked_within_2mm']}（≤2mm即出现几何阻挡）。",'这不等于任意路径的防脱证明，也不是保持盖承载试验。','','## CAD与后续工作','',f"单件STEP通过回读：{len(cad['parts'])}件；OBJ/STL几何回读：{checks['all_geometry_checks_pass']}。",'cad/SC_review_assembly.step为分面BRep装配查看文件，保持12个独立实体，不包含原生SolidWorks装配配合。','后续仍需：SC/AC耦合路径、其余关节实体、防脱与机架安装、钢丝/TPU接口和肌肉实际变形。','原始源文件和39个支撑参考不变。']
    (dest/'SC_AND_MOTION_REVIEW.md').write_text('\n'.join(text)+'\n',encoding='utf8');print('joint review written',len(r['actions']),'paths')

if __name__=='__main__':run()
